package shinkan.core.net

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class ClientHelloTest {
    private fun hex(s: String) = s.chunked(2).map { it.toInt(16).toByte() }.toByteArray()

    // Hellos captured from Python's TLS stack (OpenSSL), 2026-11-04.
    private val one = hex("")
    private val other = hex("")

    @Test fun `the name of a real hello is read`() {
        assertEquals(ClientHello.Name("one.one.one.one"), ClientHello.read(one))
        assertEquals(ClientHello.Name("www.example.net"), ClientHello.read(other))
    }

    @Test fun `every cut of a hello needs more, and never reads wrong`() {
        for (cut in 0 until one.size) assertEquals(ClientHello.NeedMore, ClientHello.read(one, cut), "cut at $cut")
    }

    @Test fun `what is not tls is left alone at once`() {
        assertEquals(ClientHello.Nameless, ClientHello.read("GET / HTTP/1.1".toByteArray()))
    }

    @Test fun `a record that is no hello is left alone`() {
        val alert = one.copyOf().also { it[5] = 2 }
        assertEquals(ClientHello.Nameless, ClientHello.read(alert))
    }

    @Test fun `a hello without the extension is nameless`() {
        // The server name extension's type changed, so nothing names a host.
        val hello = one.copyOf()
        val at = hello.indices.first { i -> i + 9 < hello.size && hello[i].toInt() == 0 && hello[i + 1].toInt() == 0 && hello[i + 4].toInt() == 0 && hello[i + 6].toInt() == 0 && hello[i + 7].toInt() == 0 && hello[i + 8].toInt() == 15 }
        hello[at + 1] = 99
        assertEquals(ClientHello.Nameless, ClientHello.read(hello))
    }

    @Test fun `lengths past the end read as nothing rather than fail`() {
        val random = java.util.Random(3)
        repeat(3000) {
            val broken = one.copyOf()
            repeat(4) { broken[5 + random.nextInt(broken.size - 5)] = random.nextInt(256).toByte() }
            ClientHello.read(broken)
        }
    }

    @Test fun `a record too long to be a hello is not waited for`() {
        val big = byteArrayOf(22, 3, 1, 0xff.toByte(), 0xff.toByte())
        assertEquals(ClientHello.Nameless, ClientHello.read(big))
    }

    @Test fun `known resolvers are blocked with their subdomains, and a pass lets one through`() {
        val list = Blocklist()
        assertTrue(list.blocksHost("dns.google"))
        assertTrue(list.blocksHost("mozilla.cloudflare-dns.com"))
        assertFalse(list.blocksHost("google.com"))
        assertFalse(list.copy(passes = setOf("dns.google")).blocksHost("dns.google"))
    }

    @Test fun `a resolver's ports are refused`() {
        val list = Blocklist()
        assertTrue(list.refusesPort(53) && list.refusesPort(853))
        assertFalse(list.refusesPort(443))
        assertTrue(list.dropsDatagram(853, null))
    }
}
